import { Transform } from 'class-transformer';
import {
  IsEmail,
  IsIn,
  IsOptional,
  IsString,
  Length,
  ValidateIf,
} from 'class-validator';

const trim = ({ value }: { value: unknown }) =>
  typeof value === 'string' ? value.trim() : value;

export class CreateUserDto {
  @Transform(trim)
  @IsString()
  @Length(1, 200)
  name!: string;

  @Transform(({ value }) =>
    typeof value === 'string' ? value.trim().toLowerCase() : value,
  )
  @IsEmail()
  @Length(3, 320)
  email!: string;

  // Accepted for older clients but never used; creation credentials are generated by the API.
  @IsOptional()
  @IsString()
  @Length(0, 128)
  password?: string;

  @IsIn([
    'SUPER_ADMIN',
    'IT_ADMIN',
    'HR_ADMIN',
    'BRANCH_MANAGER',
    'STAFF',
    'EMPLOYEE',
  ])
  role!: string;

  @ValidateIf((input: CreateUserDto) => input.role !== 'SUPER_ADMIN')
  @IsOptional()
  @Transform(trim)
  @IsString()
  @Length(1, 100)
  branchId?: string | null;

  @IsOptional()
  @Transform(trim)
  @IsString()
  @Length(1, 100)
  employeeId?: string;
}
